1	package ociresources
2	
3	import (
4		"errors"
5		"fmt"
6		"regexp"
7		"slices"
8		"strings"
9		"testing"
10	
11		"github.com/charmbracelet/x/ansi"
12	
13		"github.com/anthnel/devdesk/internal/cache"
14		"github.com/anthnel/devdesk/internal/config"
15		"github.com/anthnel/devdesk/internal/imagesearch"
16		"github.com/anthnel/devdesk/internal/ui/testutil"
17	)
18	
19	// DEVDESK-579 (NX-12, DEVDESK-623), step 6, UX conditions on the label of a merged
20	// group unit ("<alias> (group)", groupUnitSuffix):
21	//
22	//  1. the `?` help says what the suffix means: those images were found through the
23	//     group, and Nexus does not say which member holds each one;
24	//  2. the suffix is never cut. A long alias ("nexus-production (group)") must never
25	//     render as "nexus-production…", which reads as the group that was not
26	//     discovered. When the Registry column is too narrow, the alias gives way
27	//     (in the middle or at the end), the suffix stays whole. The same goes for
28	//     the header lines that name a registry and for the `r` filter token.
29	//
30	// The tests read the screen (Render) and the header values, never a column width,
31	// so they hold whichever way the production code keeps the suffix.
32	
33	const (
34		longGroupAlias = "nexus-production"
35		longGroupSlug  = "nxp"
36		longGroupHost  = "nexus.example.com"
37	)
38	
39	// aliasThenSuffix matches a Registry cell that keeps its suffix whole, behind an
40	// alias that may have been cut anywhere but in front of the suffix: "nexus-production (group)",
41	// "nexus-pro… (group)", "nexus…tion (group)". "nexus-production… (group)" matches
42	// too, which is fine: the suffix is there, the alias is plainly shortened.
43	var aliasThenSuffix = regexp.MustCompile(`nexus\S* ` + regexp.QuoteMeta(strings.TrimSpace(groupUnitSuffix)))
44	
45	// narrowWidths are terminal widths from the narrowest the tables still draw their
46	// Registry column in (60: dot, Name, Registry, see
47	// TestSearchTableAt60ColumnsKeepsActivityNameRegistry) up to a wide one.
48	var narrowWidths = []int{60, 64, 70, 80, 90, 100, 120, 160, 200}
49	
50	// everyWidth is every terminal width from 60 to 200: the column solver shares
51	// the room between Name, Registry and the optional columns in steps, so a cut
52	// shows up at some widths only (a few samples miss it).
53	var everyWidth = func() []int {
54		var ws []int
55		for w := 60; w <= 200; w++ {
56			ws = append(ws, w)
57		}
58		return ws
59	}()
60	
61	// longAliasGroup is a group with a long alias whose two discovered members have no
62	// address of their own (the group's URL, no prefix), so a search merges them into
63	// one unit labelled longGroupAlias + groupUnitSuffix, keyed by the group's slug.
64	func longAliasGroup(provider string) config.RegistryItem {
65		g := nexusGroup()
66		g.Slug, g.Alias, g.URL, g.Provider = longGroupSlug, longGroupAlias, longGroupHost, provider
67		g.AuthMode = config.AuthAnonymous
68		return g
69	}
70	
71	func longAliasMembers() map[string]cache.RegistryGroupEntry {
72		return map[string]cache.RegistryGroupEntry{longGroupSlug: {Members: []cache.RegistryGroupMember{
73			{Alias: "docker-hosted", URL: longGroupHost},
74			{Alias: "docker-proxy", URL: longGroupHost},
75		}}}
76	}
77	
78	// groupUnitLot opens the browser on the long-alias group (and on items besides),
79	// at the given width, and starts the search of the lot. No answer is in yet.
80	func groupUnitLot(t *testing.T, width int, provider string, others ...config.RegistryItem) Model {
81		t.Helper()
82		withImageSearcher(t, &fakeSearcher{})
83		items := append([]config.RegistryItem{longAliasGroup(provider)}, others...)
84		m := modelWithGroups(t, items, longAliasMembers())
85		m = feed(t, m, testutil.Resize(width, 40))
86		m = searchLot(t, m)
87		if m.registryBrowser.entryFor(longGroupSlug) == nil {
88			t.Fatal("the lot made no unit for the group: the test does not set up what it claims to")
89		}
90		return m
91	}
92	
93	// lineWith returns the first line of the screen (viewport and footer, where the
94	// filter bar lives) containing needle.
95	func lineWith(t *testing.T, m Model, needle string) string {
96		t.Helper()
97		screen := ansi.Strip(m.Render() + "\n" + m.RenderFooter(m.width))
98		for _, line := range strings.Split(screen, "\n") {
99			if strings.Contains(line, needle) {
100				return line
101			}
102		}
103		t.Fatalf("no line of the screen contains %q:\n%s", needle, screen)
104		return ""
105	}
106	
107	// wantSuffixKept fails when the line shows the alias without its whole suffix.
108	func wantSuffixKept(t *testing.T, where, line string) {
109		t.Helper()
110		if !aliasThenSuffix.MatchString(line) {
111			t.Errorf("%s: the Registry cell lost the suffix %q:\n%s", where, groupUnitSuffix, line)
112		}
113	}
114	
115	// ---- (a) the help ----------------------------------------------------------
116	
117	// The `?` help explains what "<alias> (group)" means, in the Registry Browser
118	// section, where the image search is described. Rule 114: the section follows the
119	// form's mode, and without a Searcher there is no search, so no group unit and
120	// nothing to explain.
121	func TestTheHelpExplainsTheGroupUnitLabel(t *testing.T) {
122		suffix := strings.TrimSpace(groupUnitSuffix)
123		wants := []string{suffix, "found through the group", "Nexus does not say which member holds each one"}
124	
125		t.Run("with a Searcher", func(t *testing.T) {
126			body := registryBrowserHelp(t, lvl1ImagesModel(t))
127			for _, want := range wants {
128				if !strings.Contains(body, want) {
129					t.Errorf("the Registry Browser help lacks %q", want)
130				}
131			}
132		})
133		t.Run("without a Searcher", func(t *testing.T) {
134			m := lvl1ImagesModel(t)
135			m.registryBrowser.searcher = nil
136			if body := registryBrowserHelp(t, m); strings.Contains(body, suffix) {
137				t.Errorf("the help explains %q although there is no search to produce it", suffix)
138			}
139		})
140	}
141	
142	// The new sentence is the only change to the help's shape: every key binding still
143	// has a key and a capitalized description, and no section is empty.
144	func TestTheHelpStaysWellFormedWithTheGroupUnitSentence(t *testing.T) {
145		c := lvl1ImagesModel(t).GetHelpContent()
146		for _, kb := range c.KeyBindings {
147			if kb.Key == "" || kb.Description == "" {
148				t.Errorf("key binding %+v has an empty key or description", kb)
149				continue
150			}
151			if first := kb.Description[:1]; first != strings.ToUpper(first) {
152				t.Errorf("description of %q does not start with a capital: %q", kb.Key, kb.Description)
153			}
154		}
155		for _, s := range c.Sections {
156			if s.Title == "" || strings.TrimSpace(s.Body) == "" {
157				t.Errorf("section %q is empty", s.Title)
158			}
159		}
160	}
161	
162	// ---- (b) the suffix is never cut -------------------------------------------
163	
164	// Level 1, the Registry column (SizingContent, MinWidth 16): at every width the row
165	// of the unit keeps " (group)" whole, even when the alias plus the suffix (24 cells)
166	// exceeds the column.
167	func TestTheSearchTableNeverCutsTheGroupSuffix(t *testing.T) {
168		for _, w := range everyWidth {
169			t.Run(fmt.Sprintf("width %d", w), func(t *testing.T) {
170				m := groupUnitLot(t, w, config.ProviderNexus)
171				m = answerFor(t, m, longGroupSlug, oneImage("webapp"), false, nil)
172	
173				line := lineWith(t, m, "webapp")
174				wantSuffixKept(t, fmt.Sprintf("level 1 at %d columns", w), line)
175				if strings.Contains(line, longGroupAlias+"…") && !strings.Contains(line, longGroupAlias+"… "+strings.TrimSpace(groupUnitSuffix)) {
176					t.Errorf("level 1 at %d columns reads as the undiscovered group %q:\n%s", w, longGroupAlias+"…", line)
177				}
178			})
179		}
180	}
181	
182	// Level 2, the Registry column of the tag table (MinWidth 20), reached with → on a
183	// row of the unit.
184	func TestTheTagTableNeverCutsTheGroupSuffix(t *testing.T) {
185		for _, w := range everyWidth {
186			t.Run(fmt.Sprintf("width %d", w), func(t *testing.T) {
187				withTagRecorder(t)
188				m := groupUnitLot(t, w, config.ProviderNexus)
189				m = answerFor(t, m, longGroupSlug, oneImage("webapp"), false, nil)
190				m = selectLevelOneRow(t, m, longGroupSlug, "library/webapp")
191				m, _, loaded := pressRight(t, m)
192	
193				if m.registryBrowser.state != browserStateTags || len(loaded) == 0 {
194					t.Fatalf("→ did not open the tags of the unit (state %d, %d answers)", m.registryBrowser.state, len(loaded))
195				}
196				rows := m.registryBrowser.tagTable.Visible()
197				if len(rows) == 0 || rows[0].label != longGroupAlias+groupUnitSuffix {
198					t.Fatalf("the tag rows are %+v, want the unit's label %q", rows, longGroupAlias+groupUnitSuffix)
199				}
200				wantSuffixKept(t, fmt.Sprintf("level 2 at %d columns", w), lineWith(t, m, "v1"))
201			})
202		}
203	}
204	
205	// The header lines that name a registry: whatever the width, a name that appears is
206	// the unit's whole label. fitNames may replace the list by "+N" when nothing
207	// fits (C4), it must never print the alias without its suffix. At a width where
208	// the label fits, it is there in full.
209	func TestTheHeaderLinesNeverCutTheGroupSuffix(t *testing.T) {
210		label := longGroupAlias + groupUnitSuffix
211		tests := []struct {
212			name     string
213			provider string
214			key      string
215			answer   func(t *testing.T, m Model) Model
216		}{
217			{"Cached only", config.ProviderNexus, "Cached only", func(t *testing.T, m Model) Model {
218				return answerFor(t, m, longGroupSlug, oneImage("webapp"), false, nil)
219			}},
220			{"Failed", config.ProviderNexus, "Failed", func(t *testing.T, m Model) Model {
221				return answerFor(t, m, longGroupSlug, nil, false, errors.New("boom"))
222			}},
223			{"Refused", config.ProviderNexus, "Refused", func(t *testing.T, m Model) Model {
224				return answerFor(t, m, longGroupSlug, nil, false, imagesearch.ErrUnsupported)
225			}},
226			// A group that is not Nexus is not cache-only: its empty answer is "No result".
227			{"No result", config.ProviderGeneric, "No result", func(t *testing.T, m Model) Model {
228				return answerFor(t, m, longGroupSlug, nil, false, nil)
229			}},
230		}
231		for _, tt := range tests {
232			for _, w := range narrowWidths {
233				t.Run(fmt.Sprintf("%s at %d", tt.name, w), func(t *testing.T) {
234					m := tt.answer(t, groupUnitLot(t, w, tt.provider))
235					_, vals := headerLines(m)
236					v, ok := vals[tt.key]
237					if !ok {
238						t.Fatalf("no %q line in the header (%v)", tt.key, vals)
239					}
240					if strings.Contains(v, "nexus") && !strings.Contains(v, label) {
241						t.Errorf("%s = %q names the group without its suffix, want %q or a bare count", tt.key, v, label)
242					}
243					if w >= 200 && !strings.Contains(v, label) {
244						t.Errorf("%s = %q at %d columns, want the whole label %q (it fits)", tt.key, v, w, label)
245					}
246				})
247			}
248		}
249	}
250	
251	// ---- (c) the `r` filter on the unit ----------------------------------------
252	
253	// lotWithUnitAndHub is the group unit next to a plain registry, so the lot has
254	// something to filter down to. Both have one image.
255	func lotWithUnitAndHub(t *testing.T, width int) Model {
256		t.Helper()
257		m := groupUnitLot(t, width, config.ProviderNexus, anonymousRegistry("docker.io", "hub"))
258		m = answerFor(t, m, longGroupSlug, oneImage("webapp"), false, nil)
259		return answerFor(t, m, "hub", oneImage("nginx"), false, nil)
260	}
261	
262	// `r` stops, in order: the group (its own label, the unit's rows), the unit (label
263	// with its suffix: a space and parentheses in a label change nothing, the filter
264	// is a key and not a parsed token), the plain registry, then off. Each stop keeps
265	// exactly its rows, and the token the bar shows is the stop's whole label.
266	func TestTheRegistryFilterSelectsTheGroupUnitExactly(t *testing.T) {
267		unit := longGroupAlias + groupUnitSuffix
268		stops := []struct {
269			label string
270			rows  []string
271		}{
272			{longGroupAlias, []string{longGroupSlug + ":library/webapp"}},
273			{unit, []string{longGroupSlug + ":library/webapp"}},
274			{"hub", []string{"hub:library/nginx"}},
275		}
276	
277		m := lotWithUnitAndHub(t, 200)
278		b := m.registryBrowser
279		if got := repoKeys(m); !slices.Equal(got, sorted([]string{longGroupSlug + ":library/webapp", "hub:library/nginx"})) {
280			t.Fatalf("rows before the filter = %v", got)
281		}
282		for i, stop := range stops {
283			m = feed(t, m, testutil.Key("r"))
284			if got := repoKeys(m); !slices.Equal(got, stop.rows) {
285				t.Errorf("stop %d (%s): rows = %v, want %v", i, stop.label, got, stop.rows)
286			}
287			if got := b.filterLabel(b.searchFilter); got != stop.label {
288				t.Errorf("stop %d: label = %q, want %q", i, got, stop.label)
289			}
290			// The token in the bar: the label as is, not split at the space, not cut at
291			// the parenthesis.
292			if line := lineWith(t, m, "/ search"); !strings.Contains(line, stop.label) {
293				t.Errorf("stop %d: the filter bar does not show %q:\n%s", i, stop.label, line)
294			}
295		}
296		m = feed(t, m, testutil.Key("r"))
297		if !b.searchFilter.isEmpty() || len(rowsOf(m)) != 2 {
298			t.Errorf("after the last stop: filter = %+v, rows = %v, want off and 2 rows", b.searchFilter, rowsOf(m))
299		}
300	}
301	
302	// The filter token, on a terminal as narrow as the tables allow, keeps the suffix
303	// when it is the unit's stop.
304	func TestTheFilterTokenNeverCutsTheGroupSuffix(t *testing.T) {
305		for _, w := range narrowWidths {
306			t.Run(fmt.Sprintf("width %d", w), func(t *testing.T) {
307				m := lotWithUnitAndHub(t, w)
308				m = feed(t, m, testutil.Key("r"), testutil.Key("r")) // the group, then the unit
309				b := m.registryBrowser
310				if got := b.filterLabel(b.searchFilter); got != longGroupAlias+groupUnitSuffix {
311					t.Fatalf("second stop = %q, want the unit's label", got)
312				}
313				wantSuffixKept(t, fmt.Sprintf("filter bar at %d columns", w), lineWith(t, m, "/ search"))
314			})
315		}
316	}
