120	func (m *Model[T]) rowLine(cols []table.Column, item T, selected bool) string {
121		_, busy := m.busyLabel(item)
122	
123		var line strings.Builder
124		for i, c := range m.cfg.Columns {
125			if i >= len(cols) || cols[i].Width <= 0 {
126				continue
127			}
128			state := indicator.Idle
129			if c.Indicator != nil {
130				state = m.indicatorState(c, item, busy)
131			}
132			text := c.Cell(item)
133			if state != indicator.Idle {
134				text = indicator.Glyph(state, m.blinkOn)
135				// Padded with runewidth, not lipgloss: lipgloss always counts an
136				// ambiguous-width glyph as one cell, runewidth follows the terminal.
137				fitted := runewidth.FillRight(text, cols[i].Width)
138				line.WriteString(m.indicatorCellStyle(state, selected).Render(fitted))
139				continue
140			}
141			fitted := fit(text, cols[i].Width, c.TruncateHead)
142			if !busy && (!selected || m.preserveColumnColors) {
143				if runs, ok := m.multiRunCell(c, item, fitted, selected); ok {
144					line.WriteString(runs)
145					continue
146				}
147			}
148			line.WriteString(m.cellStyle(c, item, selected, busy).Render(fitted))
149		}
150		if selected {
151			return m.styles.Selected.Render(m.padToContent(line.String()))
152		}
153		return line.String()
154	}
155	
156	// padToContent pins the selected row to the full content width (m.width-2) so
157	// the highlight reaches the right border when the columns span less than the
158	// viewport. The gap is computed from the column widths, never by re-measuring
159	// the rendered line: cells are fitted by lipgloss (ansi widths) and a second
160	// measure with another library disagrees on emoji and flags. On the plain
161	// "normal" selection the gap is painted with ColorTableLineSelected itself, as
162	// every cell is, because it follows the last cell's reset.
163	func (m *Model[T]) padToContent(line string) string {
164		gap := m.width - 2 - m.RenderedWidth()
165		if m.width <= 2 || gap <= 0 {
166			return line
167		}
168		pad := strings.Repeat(" ", gap)
169		if m.preserveColumnColors {
170			pad = lipgloss.NewStyle().Background(theme.ColorTableLineSelected).Bold(true).Render(pad)
171		}
172		return line + pad
173	}
