187	func (m *Model[T]) indicatorCellStyle(state indicator.State, selected bool) lipgloss.Style {
188		if selected {
189			if !m.preserveColumnColors {
190				return m.styles.Cell
191			}
192			return indicator.Style(state).Padding(0, 1).Background(theme.ColorTableLineSelected).Bold(true)
