197	// fit truncates the text to the column and pads it out, emitting no escape
198	// sequence of its own — the caller styles what comes back. Doing it in that
199	// order is the whole point of this file: an escape sequence's bytes would count
200	// as width, so text has to be measured while it is still plain.
201	//
202	// Measuring, cutting and padding all go by grapheme clusters, the primitive
203	// x/ansi sums in StringWidth, so a cell is exactly as wide as Lip Gloss and the
204	// viewport think it is, VS16 emoji and keycaps included (DEVDESK-280).
205	func fit(text string, width int, head bool) string {
206		if width <= 0 {
207			return ""
208		}
209		// A cell is one line. Lip Gloss Inline(true), which this replaced, deleted
210		// line breaks outright; so does this, only when there is one to delete.
211		if strings.ContainsAny(text, "\r\n") {
212			text = lineBreaks.Replace(text)
213		}
214		// Inline(true) also turned a tab into four spaces; a raw tab measures 0.
215		if strings.Contains(text, "\t") {
216			text = strings.ReplaceAll(text, "\t", "    ")
217		}
218		var cut string
219		if head {
220			cut = truncateHead(text, width)
221		} else {
222			cut = truncateTail(text, width)
223		}
224		if pad := width - cellWidth(cut); pad > 0 {
225			// A trailing Prepend character is invisible and would merge with the
226			// first padding space into one zero-width cluster.
227			cut = strings.TrimRightFunc(cut, isPrepend)
228			cut += strings.Repeat(" ", pad)
229		}
230		return cut
231	}
232	
233	// isPrepend reports the Prepend grapheme-break characters, which attach to the
234	// character after them.
235	func isPrepend(r rune) bool {
236		return r >= 0x0600 && r <= 0x0605 || r == 0x06DD || r == 0x070F || r == 0x08E2
237	}
238	
239	// lineBreaks deletes every kind of line break from a cell.
240	var lineBreaks = strings.NewReplacer("\r\n", "", "\n", "", "\r", "")
241	
242	// cellWidth is the width of text in terminal cells, summed per grapheme
243	// cluster. It equals ansi.StringWidth for any input.
244	func cellWidth(text string) int {
245		total := 0
246		for len(text) > 0 {
247			cluster, w := ansi.FirstGraphemeCluster(text, ansi.GraphemeWidth)
248			if cluster == "" {
249				break
250			}
251			total += w
252			text = text[len(cluster):]
253		}
254		return total
255	}
256	
257	// truncateTail keeps the start of text, ending it with the marker when
258	// something is cut. It never splits a grapheme cluster, and the result is never
259	// wider than width.
260	func truncateTail(text string, width int) string {
261		if width <= 0 {
262			return ""
263		}
264		if cellWidth(text) <= width {
265			return text
266		}
267		marker := cellWidth(truncationMarker)
268		if width < marker {
269			return ""
270		}
271		budget := width - marker
272		var b strings.Builder
273		used := 0
274		for rest := text; rest != ""; {
275			cluster, w := ansi.FirstGraphemeCluster(rest, ansi.GraphemeWidth)
276			if cluster == "" || used+w > budget {
277				break
278			}
279			b.WriteString(cluster)
280			used += w
281			rest = rest[len(cluster):]
282		}
283		return b.String() + truncationMarker
284	}
285	
286	// truncateHead keeps the *end* of the text, for the columns that declare it
287	// (Column.TruncateHead).
288	//
289	// A column of URLs, image references or paths shares its prefix on every row,
290	// so cutting the tail renders three identical cells that identify nothing —
291	// and it does so precisely when the column is squeezed to its floor, which is
292	// when it is hardest to read. Keeping the end is what tells the rows apart.
293	//
294	// Cells rather than runes throughout: a cell is measured in terminal cells,
295	// and a CJK name counts two per rune. The cut falls on a cluster boundary.
296	func truncateHead(text string, width int) string {
297		if width <= 0 || cellWidth(text) <= width {
298			return text
299		}
300		marker := cellWidth(truncationMarker)
301		if width <= marker {
302			// No room for the marker and anything after it. Saying "there is more"
303			// with no idea what beats a single arbitrary character.
304			return truncateTail(truncationMarker, width)
305		}
306		// Drop clusters from the front until the rest fits next to the marker.
307		skip := cellWidth(text) - (width - marker)
308		dropped := 0
309		for text != "" && dropped < skip {
310			cluster, w := ansi.FirstGraphemeCluster(text, ansi.GraphemeWidth)
311			if cluster == "" {
312				break
313			}
314			dropped += w
315			text = text[len(cluster):]
316		}
317		// A wide cluster straddling the cut leaves a hole: it sits after the marker,
318		// so the kept end stays flush right.
319		hole := width - marker - cellWidth(text)
320		return truncationMarker + strings.Repeat(" ", max(hole, 0)) + text
321	}
